<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { collectionUrl } from '../services/collectionPage.js';
import { galleryImages } from '../data/gallery.js';
import { galleryCollectionExamples } from '../data/galleryCollections.js';
import { galleryManager } from '../services/galleryManagement.js';
import { cloudConfigured, findCloudGalleryImage } from '../services/galleryCloud.js';
const route=useRoute();
const collections=ref([...galleryCollectionExamples]);const cloudImages=ref([]);const busy=ref(false);const error=ref('');const shareMessage=ref('');
let alive=true;let request=0;
const selected=computed(()=>collections.value.find(item=>item.id===route.params.id));
const items=computed(()=>{const lookup=new Map([...galleryImages,...cloudImages.value].map(item=>[item.id,item]));return (selected.value?.imageIds||[]).map(id=>lookup.get(id)).filter(Boolean);});
const base=import.meta.env.BASE_URL;
const imageSrc=image=>/^(https?:|data:)/.test(image.thumbnail||image.src)?(image.thumbnail||image.src):`${base}${image.thumbnail||image.src}`;
function cover(collection){const image=[...galleryImages,...cloudImages.value].find(item=>item.id===(collection.cover_image_id||collection.imageIds[0]));return image?imageSrc(image):'';}
async function load(){if(!cloudConfigured)return;const revision=++request;busy.value=true;error.value='';try{const rows=await galleryManager.collections();if(!alive||revision!==request)return;collections.value=[...galleryCollectionExamples,...rows];const ids=[...new Set(rows.flatMap(row=>[row.cover_image_id,...row.imageIds]).filter(id=>id?.startsWith('cloud-')))];const results=[];for(let offset=0;offset<ids.length;offset+=4){const batch=await Promise.all(ids.slice(offset,offset+4).map(id=>findCloudGalleryImage(id)));results.push(...batch.filter(Boolean));if(!alive||revision!==request)return;}cloudImages.value=results;}catch(cause){if(alive&&revision===request)error.value='云端合集暂时无法读取。本站策展仍可查看，可以稍后重试。';}finally{if(alive&&revision===request)busy.value=false;}}
async function share(){const url=selected.value?.static?collectionUrl(selected.value.id):location.href;try{await navigator.clipboard.writeText(url);shareMessage.value='合集链接已复制。';}catch{shareMessage.value=`复制此链接分享：${url}`;}}
watch(()=>selected.value?.title,title=>{document.title=`${title||'主题合集'} · 一里小屋`;},{immediate:true});
onMounted(load);onBeforeUnmount(()=>{alive=false;request++;});
</script>
<template><main id="main" class="collections-page" tabindex="-1"><div class="collections-paper"><header><RouterLink to="/room/play">← 回到活动室</RouterLink><span>HITORI ROOM / CURATED MOMENTS</span><h1>{{route.params.id?(selected?.title||'寻找这份合集'):'把喜欢，串成一册'}}</h1><p>演出前、放学后，还有四个人在一起的日常。每张图片沿用原有来源记录。</p></header><p v-if="busy" role="status">正在读取云端合集…</p><p v-if="error" role="alert" class="collections-error">{{error}} <button @click="load">重试</button></p>
<template v-if="route.params.id"><template v-if="selected"><p class="collection-description">{{selected.description}}</p><div class="collection-controls"><RouterLink to="/collections">全部合集</RouterLink><button type="button" @click="share">复制合集链接</button><span>{{items.length}} 张可用图片</span></div><p v-if="shareMessage" role="status">{{shareMessage}}</p><div v-if="items.length" class="collection-image-grid"><RouterLink v-for="image in items" :key="image.id" :to="{path:'/',query:{image:image.id},hash:'#gallery'}"><img :src="imageSrc(image)" :alt="image.alt||image.title" loading="lazy"><strong>{{image.title}}</strong><small>{{image.credit}}</small></RouterLink></div><p v-else-if="!busy" class="collection-empty">这册还在慢慢收集。图片可能已下架，或尚未加入，稍后再来看看。</p></template><p v-else-if="!busy" class="collection-empty">这份合集暂时不可用，可能尚未公开或已移除。<RouterLink to="/collections">去看其他合集 ↗</RouterLink></p></template>
<div v-else class="collection-card-grid"><RouterLink v-for="collection in collections" :key="collection.id" :to="`/collections/${collection.id}`"><img v-if="cover(collection)" :src="cover(collection)" :alt="collection.title" loading="lazy"><div v-else class="collection-cover-empty" aria-hidden="true">✦</div><span>{{collection.static?'本站策展':'站主主题册'}} · {{collection.imageIds.length}} 张</span><h2>{{collection.title}}</h2><p>{{collection.description}}</p></RouterLink></div>
<footer><RouterLink :to="{path:'/',hash:'#gallery'}">回到收藏墙 ↗</RouterLink><RouterLink to="/manage-gallery">站主管理合集</RouterLink></footer></div></main></template>
<style scoped>
.collections-page{min-height:100dvh;padding:120px 24px 50px;background:#171522;color:#493b47}.collections-paper{max-width:1080px;margin:auto;background:#f8eddd;padding:clamp(22px,5vw,55px);box-shadow:10px 12px 0 #a87593}.collections-paper header{border-bottom:2px solid #69435b;padding-bottom:24px}.collections-paper header>a{display:block;margin-bottom:20px}.collections-paper header>span{font-size:11px;letter-spacing:.12em;color:#8f5975}.collections-paper h1{font-size:clamp(28px,5vw,48px);line-height:1.3;margin:20px 0}.collections-paper p{font-size:14px;line-height:1.9;overflow-wrap:anywhere}.collections-paper a{color:inherit}.collection-card-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;margin-top:30px}.collection-card-grid>a{display:block;border:1px solid #bca3af;background:#fffbf3;padding:14px;text-decoration:none;box-shadow:3px 4px 0 #dcc3ce}.collection-card-grid img,.collection-cover-empty{display:block;width:100%;height:190px;object-fit:cover;background:#e6d3dc}.collection-cover-empty{display:grid;place-items:center;font-size:60px;color:#a56e8e}.collection-card-grid span{display:block;font-size:11px;color:#846477;margin-top:15px}.collection-card-grid h2{font-size:22px;line-height:1.5;margin:12px 0}.collection-card-grid p{font-size:13px}.collection-controls{display:flex;flex-wrap:wrap;align-items:center;gap:14px;margin:24px 0;font-size:13px}.collection-controls :is(a,button),footer a{display:inline-flex;align-items:center;min-height:44px;padding:10px 16px;background:#6c405b;color:#fff8ee;font:inherit;border:1px solid #6c405b;text-decoration:none;cursor:pointer}.collection-image-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.collection-image-grid a{text-decoration:none;display:grid;align-content:start;background:#fffbf3;padding:12px;gap:12px}.collection-image-grid img{width:100%;height:230px;object-fit:contain}.collection-image-grid strong{font-size:15px}.collection-image-grid small{font-size:11px;line-height:1.8;color:#806476}.collection-empty{padding:30px;background:#ead9e0}.collection-empty a{display:block;min-height:44px;padding-top:12px}.collections-paper footer{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;margin-top:40px;padding-top:20px;border-top:1px solid #bda6b2;font-size:13px}.collections-error{color:#9b2449}.collections-error button{min-height:44px;padding:10px 16px}@media(max-width:850px){.collection-card-grid,.collection-image-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.collections-page{padding:95px 16px 35px}.collections-paper{box-shadow:5px 6px 0 #a87593}.collection-card-grid,.collection-image-grid{grid-template-columns:1fr}.collection-card-grid img{height:200px}}
</style>
